function fuelBaseSlot(slot:PartsSlot,version:string,fuel:Fuel,tier:string,maxPower:number):PartsSlot{
 if(slot.id==='regulator'){const retainOem=version.startsWith('m')&&maxPower>0&&maxPower<=400;const candidate=undefined;return {...slot,alternatives:(fuelFabricationOptions.regulator??[]).filter(k=>fuel==='petrol'||k!=='fuel_USA_AEM_25_302BK'),defaultNone:true,candidate,planNote:retainOem?['Modernizacja opcjonalna. Można rozważyć pozostawienie seryjnego regulatora, jeśli utrzymuje wymagane ciśnienie różnicowe na wtryskiwaczach pod doładowaniem i odpowiedni przepływ. W BMW położenie regulatora zależy od wersji (listwa lub układ przy filtrze). Zmierz ciśnienie pod obciążeniem; w razie potrzeby zastosuj regulator 1:1 z powrotem.','Optional upgrade. Retain the OEM regulator only if required injector differential pressure and flow under boost are maintained. BMW regulator location depends on version (rail or filter system). Measure under load; use a 1:1 return-style regulator if needed.']:['Sprawdź wymagane ciśnienie różnicowe pod doładowaniem. Dobierz regulator 1:1, przepływ, paliwo i porty; AEM 25-302BK tylko do benzyny.','Verify required differential pressure under boost. Size 1:1 regulator, flow, fuel and ports; AEM 25-302BK gasoline only.']};}
 if(slot.id==='rail')return {...slot,alternatives:fuelFabricationOptions[version==='2jz-ge'?'rail-ge':version==='2jz-gte'?'rail-gte':'rail-bmw']??[],defaultNone:true,candidate:undefined,planNote:['Modernizacja opcjonalna. Seryjną listwę można pozostawić, jeśli pasuje do wtryskiwaczy, utrzymuje wymagany przepływ i ciśnienie oraz jest szczelna. Sprawdź też zawartość zestawu kolektora ssącego.','Optional upgrade. Retain the original rail if injector fitment, required flow, pressure and leak tightness are confirmed. Check intake manifold kit contents as well.']};
 if(slot.id==='fuel-lines')return {...slot,label:['Przewód paliwowy – zasilanie PTFE','PTFE fuel supply hose'],alternatives:fuelFabricationOptions.hose??[],defaultNone:true,candidate:undefined,planNote:['Dobierz AN i długość do wydajności pompy, ciśnienia i trasy.','Match AN size and length to pump flow, pressure and routing.']};
 return slot;
}
function fuelFabricationSlots():PartsSlot[]{
 const row=(id:string,label:[string,string],family:string,qty:number|null,note:[string,string]):PartsSlot=>({id,label,alternatives:fuelFabricationOptions[family]??[],conditional:true,qty,defaultNone:true,planNote:note});
 const hoseNote:[string,string]=['Rozmiar i długość do potwierdzenia po ustaleniu trasy.','Confirm size and length after routing is established.'];
 const fittingNote:[string,string]=['Dobierz końcówki do rozmiaru wybranego przewodu i rzeczywistej liczby połączeń; adaptery portów osobno.','Match hose ends to selected hose size and actual connection count; port adapters separately.'];
 return [
 row('fuel-return',['Przewód paliwowy – powrót PTFE','PTFE fuel return hose'],'hose',null,hoseNote),
 row('fuel-post-filter',['Filtr dokładny za pompą','Post-pump fine filter'],'post-filter',1,['Dodatkowy filtr tylko w razie potrzeby modernizacji. Sprawny seryjny filtr można pozostawić po potwierdzeniu przepływu, ciśnienia i zgodności z paliwem. Filtracja dokładna nadal jest wymagana.','Additional filter only if an upgrade is needed. Retain a serviceable original filter after confirming flow, pressure and fuel compatibility. Fine filtration is still required.']),
 row('fuel-pre-filter',['Filtr wstępny przed pompą zewnętrzną','External pump pre-filter'],'pre-filter',1,['Dodatkowy filtr wstępny dobierz do wymagań pompy zewnętrznej. Pompa w zbiorniku może mieć własny kosz ssawny; nie dubluj filtracji bez potrzeby.','Select an additional pre-filter to suit external pump requirements. An in-tank pump may have its own strainer; avoid unnecessary duplication.']),
 ...(['feed','return'] as const).flatMap(side=>(['straight','45','90'] as const).map(angle=>row('fuel-end-'+side+'-'+angle,[('Końcówki PTFE '+(angle==='straight'?'proste':angle+'°')+' – '+(side==='feed'?'zasilanie':'powrót')),('PTFE '+angle+' hose ends – '+side)],'fitting-'+angle,null,fittingNote))),
 {id:'fuel-port-adapters',label:['Adaptery portów i korki paliwowe','Fuel port adapters and plugs'],qty:null,conditional:true,defaultNone:true,planNote:['Potwierdź typ portu AN/JIC, ORB lub NPT, gwint i uszczelnienie.','Confirm AN/JIC, ORB or NPT port type, thread and seal.']}
 ];
}

/** FMIC straight 4-ply couplers: nominal wall 5.5 mm. Supplier explicitly
 * lists SGB 68–73 for 57 mm and 74–79 for 63 mm. Other sizes are estimates. */
export function chargeClampSuggestion(couplerKey:string|undefined,candidateMap:Record<string,BuildCandidate>=intakeFabricationCandidates){
 const c=couplerKey?candidateMap[couplerKey]:undefined;
 if(c?.variant?.family!=='charge-couplers')return null;
 const inner=c.variant.diameterMm,outer=inner+11;
 const ranges:Record<number,[string,string]>={51:['intake_OBSGB6063','60–63'],57:['intake_OBSGB6873','68–73'],63:['intake_OBSGB7479','74–79'],70:['intake_OBSGB8085','80–85'],76:['intake_OBSGB8691','86–91']};
 const match=ranges[inner];return match?{key:match[0],range:match[1],inner,outer}:null;
}

function oilCoolingSlot(slot:PartsSlot,version:string,tier:string,usage:string):PartsSlot{
 const options=oilCoolingOptions;
 const update=(keys:string[],note:[string,string],label?:[string,string]):PartsSlot=>({...slot,...(label?{label}:{}),alternatives:keys,defaultNone:true,candidate:undefined,qty:1,planNote:note});
 if(slot.id==='oil-cooler'){
  const preferred=usage==='street'?'13':tier==='premium'?'25':'19';
  const base='oilcool_OIL_'+preferred+'_FMICPRO_B';
  const keys=options['oil-cooler']??[];
  return update(keys.includes(base)?[base,...keys.filter(k=>k!==base)]:keys,['Orientacyjna propozycja rozmiaru; rzeczywisty dobór wg temperatury oleju, przepływu powietrza i spadku ciśnienia.','Indicative size suggestion; final sizing depends on oil temperature, airflow and pressure drop.']);
 }
 if(slot.id==='breather')return update(options.breather??[],['Dobierz pojemność i króćce do układu odmy.','Match capacity and fittings to ventilation layout.']);
 if(slot.id==='oil-thermostat')return update(options['oil-thermostat']??[],['Termostat liniowy; sprawdź czy nie jest już w adapterze.','Inline thermostat; check whether already included in adapter.'],['Termostat chłodnicy oleju','Oil cooler thermostat']);
 if(slot.id==='radiator')return update([...options['radiator-bmw']??[],...options['radiator-supra']??[]],['Dobierz do NADWOZIA, nie tylko silnika. W swapie potwierdź miejsce i przyłącza.','Select by CHASSIS, not just engine. Verify space and connections on swaps.'],['Chłodnica cieczy','Coolant radiator']);
 if(slot.id==='water-pump'&&(version.startsWith('m50')||version.startsWith('m52')))return update(options['water-pump-bmw']??[],['Pompa wody: potwierdź numer OE i wersję silnika; termostat dobierz osobno.','Water pump: confirm OE number and engine version; select thermostat separately.'],['Pompa wody','Water pump']);
 return slot;
}
function oilCoolingExtraSlots(version:string):PartsSlot[]{
 const adapter=version.startsWith('m50')?'adapter-m50':version.startsWith('m52')||version.startsWith('m54')?'adapter-m52-m54':'adapter-2jz';
 const row=(id:string,label:[string,string],keys:string[],note:[string,string],qty:number|null=1):PartsSlot=>({id,label,alternatives:keys,qty,defaultNone:true,conditional:true,planNote:note});
 return [
 row('oil-cooler-adapter',['Adapter chłodnicy oleju','Oil cooler adapter'],oilCoolingOptions[adapter]??[],['Potwierdź podstawę filtra, gwinty, uszczelnienie i komplet wyjść; adapter 2JZ może wymagać dodatkowej podstawki.','Confirm filter housing, threads, seals and outlet kit; 2JZ adapter may require sandwich plate.']),
 row('cooling-fan',['Wentylator chłodnicy','Radiator fan'],oilCoolingOptions['cooling-fan']??[],['Dobierz wymiary, kierunek pracy i wydajność do chłodnicy; podaj liczbę sztuk.','Match dimensions, direction and airflow to radiator; enter quantity.'],null)
 ];
}
